// Original input, actual RTL fault/recovery qualification. Register injections are
// verification-only on exposed Q, never production command ports or oracle input.
#define main v97_pilot_main
#include "sim.cpp"
#undef main
static std::ofstream failures;static unsigned errors=0,restarts=0,stage_aborts=0,injections=0,terminal_rejects=0,control_conflicts=0,done_conflicts=0;
static uint64_t saved_aborts=0,saved_stale=0;static unsigned hard_resets=0;
static void hard_reset(){saved_aborts+=d.aborts;saved_stale+=d.stale_responses;d.cmd=d.cfg=d.ack=d.soft_abort=0;hold_external=false;d.reset=1;step();d.reset=0;step();need(!d.busy&&!d.done&&d.epoch==0&&fifo.empty(),"coordinated hard reset");hard_resets++;}
static void soft_abort(){d.cmd=1;d.soft_abort=1;auto e=step();need(!e.command&&!e.cfg_req&&!e.cfg_rsp,"abort priority");d.soft_abort=0;d.cmd=0;need(!d.busy&&!d.a_valid,"abort releases and invalidates A");}
static void drain(){hold_external=false;for(int j=0;j<30&&!fifo.empty();j++)step();need(fifo.empty(),"bounded old fabric drain");}
static void until(int phase,int sub){auto begin=ticks;while(!(d.debug_state==phase&&(sub<0||(phase==2?d.vdebug:phase==5?d.mdebug:d.ndebug)==sub))){step();need(ticks-begin<30000000,"phase arrival");need(!d.done,"no early completion");}}
static void restart(const Case&c,const std::string&role){prepare(c);start();finish(c,role);restarts++;}
static void expect_error(const std::string&name,unsigned code,bool no_reads=false){wait_done();need(d.status==code,"expected actual error status");if(no_reads)need(d.transactions==t0&&fifo.empty(),"rejected command never reads external address");failures<<"{\"name\":\""<<name<<"\",\"status\":"<<unsigned(d.status)<<",\"epoch\":"<<d.epoch<<",\"transactions\":"<<d.transactions-t0<<",\"A_published\":"<<(d.a_valid?"true":"false")<<"}\n";ack();errors++;}
static void put32(std::vector<uint8_t>&v,size_t off,int64_t x){for(int j=0;j<4;j++)v[off+j]=uint32_t(x)>>(8*j);}
static void inject_epoch(uint32_t x){need(!d.busy&&fifo.empty(),"idle empty-fabric boundary injection");d.epoch=x;d.eval();need(d.epoch==x,"actual exposed register readback");step();need(d.epoch==x,"actual register holds after edge");injections++;}
static void terminal_reject(){d.cmd=1;for(int j=0;j<12;j++){need(!step().command&&!d.cmd_ready&&!d.ext_req&&!d.busy&&d.epoch==0xffffffffu,"terminal max no wrap/command");terminal_rejects++;}d.cmd=0;}
static void control_priority(){for(bool hard:{false,true}){hard_reset();config(true,512,{0xa5a5a5a5,0,0,0});d.cfg=1;d.cfg_wr=1;d.cfg_addr=512;d.cfg_take=1;d.cfg_din[0]=0xdeadbeef;d.reset=hard;d.soft_abort=!hard;d.eval();need(!d.cfg_ready&&!d.cfg_valid&&!d.done,"reset masks cfg");auto e=step();need(!e.cfg_req&&!e.cfg_rsp&&!e.command,"cancelled config handshake");d.cfg=0;d.reset=d.soft_abort=0;step();need(config(false,512)[0]==0xa5a5a5a5,"cancelled write retained canary");control_conflicts++;
 d.cfg=1;d.cfg_wr=0;d.cfg_take=0;need(step().cfg_req,"pending configuration accepted");d.cfg=0;step();need(d.cfg_valid,"pending response held");d.reset=hard;d.soft_abort=!hard;d.cfg_take=1;d.eval();need(!d.cfg_valid&&!d.cfg_ready,"reset masks pending response");e=step();need(!e.cfg_rsp,"reset cancels pending response");d.reset=d.soft_abort=0;step();need(!d.cfg_valid,"cancelled config no ghost");control_conflicts++;}}
int main(int argc,char**argv){try{Verilated::commandArgs(argc,argv);need(argc==5,"vectors output stall pilot");stall=std::stoi(argv[3]);hard_reset();std::ifstream f(argv[1]);out.open(argv[2]);failures.open(std::string(argv[2])+".failures.jsonl");std::vector<Case>cases,bounds;Case c;while(f>>c.name>>c.gu>>c.records>>c.gamma_bytes>>c.lut>>c.coefficient)cases.push_back(c);need(cases.size()==6,"six original cases");std::ifstream bf(std::filesystem::path(argv[1]).parent_path()/"boundaries.tsv");while(bf>>c.name>>c.gu>>c.records>>c.gamma_bytes>>c.lut>>c.coefficient)bounds.push_back(c);need(bounds.size()==2,"two distinct numeric boundary vectors");
 for(auto&x:cases){prepare(x);start();finish(x,"mixed");}for(auto&x:bounds){prepare(x,true);start();finish(x,"numeric-boundary",true);}
 for(int k=0;k<6;k++){prepare(cases[0]);if(k==0)d.gateup_address++;if(k==1)d.records_address=d.gateup_address;if(k==2)d.gamma_address=0x03fffff0;if(k==3)d.records_address=0x07fff000;if(k==4)d.epsilon=0;if(k==5)d.coefficient=0;start();expect_error("address-config-"+std::to_string(k),16,true);restart(cases[(k+1)%6],"restart-address-"+std::to_string(k));}
 prepare(cases[0]);put32(gu,0,1048576);put32(gu,2048,8388608);start();expect_error("MID-overflow",33);need(!d.a_valid&&!d.expert_valid,"overflow cannot publish A");restart(cases[1],"restart-mid-overflow");
 prepare(cases[0]);records[6]=1;start();expect_error("old-host-delta",1);restart(cases[2],"restart-old-host-delta");
 for(int k=0;k<3;k++){prepare(cases[0]);start();until(3,-1);unsigned before_packets=d.packets,before_macs=d.macs;unsigned wanted_owner=d.a_owner^(k==0),wanted_version=d.a_version^(k==1),wanted_epoch=d.a_epoch^(k==2);d.a_owner=wanted_owner;d.a_version=wanted_version;d.a_epoch=wanted_epoch;d.eval();step();need(d.debug_state==4&&d.a_owner==wanted_owner&&d.a_version==wanted_version&&d.a_epoch==wanted_epoch,"injected actual Q persists before M start");injections++;expect_error("A-metadata-"+std::to_string(k),17);need(d.mdebug==0&&d.packets==before_packets&&d.macs==before_macs,"rejected ownership never starts M");restart(cases[k+1],"restart-metadata-"+std::to_string(k));}
 const int phases[7][2]={{2,2},{2,9},{2,17},{5,4},{5,21},{8,8},{8,21}};
 for(int k=0;k<7;k++){prepare(cases[k%6]);start();until(phases[k][0],phases[k][1]);soft_abort();drain();stage_aborts++;restart(cases[(k+1)%6],"restart-stage-"+std::to_string(k));}
 prepare(cases[0]);hold_external=true;start();while(fifo.empty())step();soft_abort();prepare(cases[1]);start();auto begin=ticks;while(fifo.size()<2){step();need(ticks-begin<200,"finite two response fabric fills");}hold_external=false;finish(cases[1],"restart-stale-response");need(d.stale_responses>=1,"actual stale response discard");restarts++;
 control_priority();prepare(cases[0]);inject_epoch(0xfffffffeu);start();finish(cases[0],"last-legal-max");terminal_reject();auto stale=d.stale_responses;fifo.push_back({0xffffffffu,0,{0,0,0,0}});step();need(fifo.empty()&&d.stale_responses==stale+1,"terminal same-tag response drained");terminal_reject();hard_reset();
 prepare(cases[0]);inject_epoch(0xfffffffeu);hold_external=true;start();while(fifo.empty())step();while(fifo.front().delay)step();hold_external=false;soft_abort();need(fifo.empty()&&d.epoch==0xffffffffu,"max abort matching response discarded");terminal_reject();hard_reset();
 prepare(cases[0],true);start();wait_done();need(d.status==0,"done priority successful actual V");d.ack=1;d.soft_abort=1;d.eval();need(!d.done,"abort suppresses held done publication");step();d.ack=d.soft_abort=0;step();done_conflicts++;need(!d.busy&&!d.a_valid,"completion aborted");hard_reset();restart(cases[5],"after-coordinated-reset");
 std::ofstream p(std::string(argv[2])+".protocol.json");p<<"{\"schema\":\"v97-qualification-v1\",\"accepted\":"<<accepted<<",\"errors\":"<<errors<<",\"restarts\":"<<restarts<<",\"stage_aborts\":"<<stage_aborts<<",\"register_injections\":"<<injections<<",\"terminal_rejected_edges\":"<<terminal_rejects<<",\"control_conflicts\":"<<control_conflicts<<",\"done_conflicts\":"<<done_conflicts<<",\"hard_resets\":"<<hard_resets<<",\"soft_aborts_actual\":"<<saved_aborts+d.aborts<<",\"stale_responses_actual\":"<<saved_stale+d.stale_responses<<",\"fabric_high_water\":"<<high_water<<",\"same_core_mixed_and_error_recovery\":true,\"held_done\":true,\"latched_parameters\":true,\"actual_production_Q_injection_declared\":true}\n";std::cout<<"PASS_ACTUAL_V_FULL_CONSUMER_RECOVERY\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<" phase="<<unsigned(d.debug_state)<<" V="<<unsigned(d.vdebug)<<" M="<<unsigned(d.mdebug)<<" N="<<unsigned(d.ndebug)<<" status="<<unsigned(d.status)<<" ticks="<<ticks<<"\n";return 1;}}
